head.script:
scwin.CHART_DATA_URL ="/ui/sample/SBChart/COLUMNS/data/COLUMNS.json";
scwin.CHART_CONFIG = {
    extend: {
        bar: {
            reference: {                          // ★ 임계값 기준 막대 색 지정
                use: true,
                condition: [">", ">", ">"],       // 비교 연산(구간별)
                value: [250, 150, 80],            // 임계값(높은→낮은)
                color: ["#e74c3c", "#f1c40f", "#2ecc71"]   // 초과 시 색(위험/경고/정상)
            }
        }
    }
};
scwin.onpageload = async function () {
    var res = await $c.sbm.executeDynamic({ id: "sbm_sbchart", action: scwin.CHART_DATA_URL, method: "get", mediatype: "application/json", mode: "asynchronous", isProcessMsg: false });
    var data = res.responseJSON;
    $c.ext.drawChartData("bar", data, chartWrap, scwin.CHART_CONFIG);
};
